from pathlib import Path
import json,hashlib
r=Path(__file__).resolve().parents[1];root=r.parents[1]
def write(name,data):(r/'build'/name).write_text(json.dumps(data,ensure_ascii=False,indent=2))
def binding(p):return {'path':str(p.relative_to(root)),'sha256':hashlib.sha256(p.read_bytes()).hexdigest()}
write('P2-story.json',{'shots':[{'id':'P2','asset':'toy-start','start_frame':0,'end_frame':180}]})
write('P2-assets.json',{'toy-start':'episodes/landing-day-one/assets/P2_toy_start.png'})
write('P2-continuity.json',{'schema_version':1,'status':'approved','reviewer':'Codex static visual inspection','story':binding(r/'build/P2-story.json'),'assets':binding(r/'build/P2-assets.json'),'additional_inputs':[binding(r/'cast-and-world.md'),binding(r/'src/doll.ts'),binding(r/'src/rig.ts')],'sources':[binding(r/'assets/P2_toy_start.png')],'cuts':[],'notes':'Single locked wide proof: six distinct characters have all feet in view on a single floor. Order in generated plate differs from written left-to-right prompt but each identity is retained. This approves starting-frame spatial clarity only, not the requested future dance.'})
url=(r/'build/P2-motion-url.txt').read_text().strip()
write('P2-motion.json',{'continuity_review':'episodes/landing-day-one/build/P2-continuity.json','jobs':[{'id':'P2_reference','shot_id':'P2','image_key':'toy-start','image':'episodes/landing-day-one/assets/P2_toy_start.png','endpoint':'minimax/h3-max/reference-to-video','duration':3,'resolution':'768P','prompt_expansion_mode':'disabled','params':{'reference_video_urls':[url],'aspect_ratio':'16:9'},'prompt':'Image 1 is the exact first frame and appearance. Video 1 is ONLY the choreography/timing reference: ignore its primitive appearance and on-screen text. Preserve the beautiful six toy characters and polished pastel floor from the first image. LOCKED full-body wide camera, all heads and all shoes always visible. All six perform ONE synchronized phrase: 0.0-0.6s raise one hand, 0.6-1.2s bring palm to sternum, 1.2-1.6s raise right heel then plant it firmly exactly at 1.6s with a small knee compression and weight transfer, 1.6-2.4s toe tap and settle, 2.4-3.0s small springboard jump and land. Legs and arms articulate naturally, supporting feet stay planted. No walking forward, no extra spins, no camera movement, no cuts, no text, no speech. Keep bodies separate with clean silhouettes. Refined animated cinema, appealing understated faces.','out':'episodes/landing-day-one/assets/P2-reference.mp4'}]})
